import type {
  UserProfile,
  FlashcardProgress,
  LessonProgress,
  QuizAttempt,
  ConversationMessage,
  LanguageCode,
  UserData,
} from "@/types";
import type { StorageProvider } from "./interface";

const STORAGE_KEY = "polyglot-data";

function getDefaultData(): UserData {
  return {
    profile: null as unknown as UserProfile,
    flashcardProgress: {},
    lessonProgress: {},
    quizAttempts: [],
    conversationHistory: {} as Record<LanguageCode, ConversationMessage[]>,
  };
}

export class LocalStorageProvider implements StorageProvider {
  private read(): UserData {
    if (typeof window === "undefined") return getDefaultData();
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return getDefaultData();
    return JSON.parse(raw);
  }

  private write(data: UserData): void {
    if (typeof window === "undefined") return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }

  async getProfile(): Promise<UserProfile | null> {
    return this.read().profile || null;
  }

  async saveProfile(profile: UserProfile): Promise<void> {
    const data = this.read();
    data.profile = profile;
    this.write(data);
  }

  async getFlashcardProgress(vocabularyId: string): Promise<FlashcardProgress | null> {
    return this.read().flashcardProgress[vocabularyId] || null;
  }

  async getAllFlashcardProgress(languageCode: LanguageCode): Promise<FlashcardProgress[]> {
    const all = this.read().flashcardProgress;
    return Object.values(all).filter((p) => p.languageCode === languageCode);
  }

  async saveFlashcardProgress(progress: FlashcardProgress): Promise<void> {
    const data = this.read();
    data.flashcardProgress[progress.vocabularyId] = progress;
    this.write(data);
  }

  async getLessonProgress(lessonId: string): Promise<LessonProgress | null> {
    return this.read().lessonProgress[lessonId] || null;
  }

  async getAllLessonProgress(languageCode: LanguageCode): Promise<LessonProgress[]> {
    const all = this.read().lessonProgress;
    return Object.values(all).filter((p) => p.languageCode === languageCode);
  }

  async saveLessonProgress(progress: LessonProgress): Promise<void> {
