"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import type { VocabularyEntry, FlashcardProgress, SM2Rating } from "@/types";
import { getStorage } from "@/lib/storage";
import { calculateSM2, createInitialProgress, isDue } from "@/lib/sm2";
import { useApp } from "./app-context";
import { getLanguageContent } from "@/data/languages";

interface FlashcardSession {
  cards: VocabularyEntry[];
  currentIndex: number;
  reviewed: number;
  correct: number;
}

interface FlashcardContextValue {
  session: FlashcardSession | null;
  currentCard: VocabularyEntry | null;
  isSessionComplete: boolean;
  startSession: () => Promise<void>;
  rateCard: (rating: SM2Rating) => Promise<void>;
  progressMap: Record<string, FlashcardProgress>;
}

const FlashcardContext = createContext<FlashcardContextValue | null>(null);

export function FlashcardProvider({ children }: { children: ReactNode }) {
  const { selectedLanguage } = useApp();
  const [session, setSession] = useState<FlashcardSession | null>(null);
  const [progressMap, setProgressMap] = useState<Record<string, FlashcardProgress>>({});

  const currentCard = session
    ? session.cards[session.currentIndex] ?? null
    : null;

  const isSessionComplete = session
    ? session.currentIndex >= session.cards.length
    : false;

  const startSession = useCallback(async () => {
    if (!selectedLanguage) return;
    const storage = getStorage();
    const content = getLanguageContent(selectedLanguage);
    const allProgress = await storage.getAllFlashcardProgress(selectedLanguage);

    const progressById: Record<string, FlashcardProgress> = {};
    for (const p of allProgress) {
      progressById[p.vocabularyId] = p;
    }

    // Cards due for review + new cards (no progress yet)
    const dueCards = content.vocabulary.filter((v) => {
      const progress = progressById[v.id];
      return !progress || isDue(progress);
    });

    // Shuffle
    for (let i = dueCards.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [dueCards[i], dueCards[j]] = [dueCards[j], dueCards[i]];
    }

    setProgressMap(progressById);
    setSession({
      cards: dueCards,
      currentIndex: 0,
      reviewed: 0,
      correct: 0,
    });
  }, [selectedLanguage]);

  const rateCard = useCallback(
    async (rating: SM2Rating) => {
      if (!session || !currentCard || !selectedLanguage) return;
      const storage = getStorage();

      const existing =
        progressMap[currentCard.id] ??
        createInitialProgress(currentCard.id, selectedLanguage);

      const updated = calculateSM2(existing, rating);
      await storage.saveFlashcardProgress(updated);

      setProgressMap((prev) => ({ ...prev, [currentCard.id]: updated }));
      setSession((prev) =>
        prev
          ? {
              ...prev,
              currentIndex: prev.currentIndex + 1,
              reviewed: prev.reviewed + 1,
              correct: rating >= 3 ? prev.correct + 1 : prev.correct,
            }
          : null
      );
    },
    [session, currentCard, selectedLanguage, progressMap]
  );

  return (
    <FlashcardContext.Provider
      value={{
        session,
        currentCard,
        isSessionComplete,
        startSession,
        rateCard,
        progressMap,
      }}
    >
      {children}
    </FlashcardContext.Provider>
  );
}

export function useFlashcards() {
  const ctx = useContext(FlashcardContext);
  if (!ctx)
    throw new Error("useFlashcards must be used within FlashcardProvider");
  return ctx;
}

