interface ProgressBarProps {
  value: number; // 0-100
  className?: string;
  color?: "primary" | "accent";
}

export function ProgressBar({
  value,
  className = "",
  color = "primary",
}: ProgressBarProps) {
  const clamped = Math.min(100, Math.max(0, value));
  const bgColor = color === "accent" ? "bg-accent" : "bg-primary";

  return (
    <div
      className={`h-2 w-full rounded-full bg-secondary ${className}`}
    >
      <div
        className={`h-full rounded-full transition-all duration-300 ${bgColor}`}
        style={{ width: `${clamped}%` }}
      />
    </div>
  );
}

