"use client";

import { useEffect, useState } from "react";
import { Card } from "@/components/ui/card";
import { ProgressBar } from "@/components/ui/progress-bar";
import { useApp } from "@/contexts/app-context";
import { getLanguageContent, getLanguage } from "@/data/languages";
import { getStorage } from "@/lib/storage";
import { isDue } from "@/lib/sm2";
import type { FlashcardProgress } from "@/types";

export function ProgressSummary() {
  const { selectedLanguage, lessonProgress } = useApp();
  const [flashcardStats, setFlashcardStats] = useState({
    total: 0,
    learned: 0,
    due: 0,
  });

  useEffect(() => {
    if (!selectedLanguage) return;
    const content = getLanguageContent(selectedLanguage);
    const storage = getStorage();

    storage.getAllFlashcardProgress(selectedLanguage).then((progress) => {
      const progressMap: Record<string, FlashcardProgress> = {};
      for (const p of progress) {
        progressMap[p.vocabularyId] = p;
      }

      const total = content.vocabulary.length;
      const learned = progress.filter((p) => p.repetitions >= 3).length;
      const due = content.vocabulary.filter((v) => {
        const p = progressMap[v.id];
        return !p || isDue(p);
      }).length;

      setFlashcardStats({ total, learned, due });
    });
  }, [selectedLanguage]);

  if (!selectedLanguage) return null;

  const language = getLanguage(selectedLanguage);
  const content = getLanguageContent(selectedLanguage);
  const completedLessons = lessonProgress.filter((l) => l.completed).length;
  const totalLessons = content.lessons.length;
  const vocabPercent =
    flashcardStats.total > 0
      ? Math.round((flashcardStats.learned / flashcardStats.total) * 100)
      : 0;

  return (
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
      <Card>
        <div className="flex items-center gap-3 mb-3">
          <span className="text-2xl">{language.flag}</span>
          <div>
            <h3 className="font-semibold text-foreground">{language.name}</h3>
            <p className="text-xs text-muted-foreground">{language.nativeName}</p>
          </div>
        </div>
        <p className="text-sm text-muted-foreground">
          {flashcardStats.total} vocabulary words
        </p>
      </Card>

      <Card>
        <h3 className="text-sm font-medium text-muted-foreground mb-2">
          Vocabulary Mastery
        </h3>
        <p className="text-2xl font-bold text-foreground mb-2">{vocabPercent}%</p>
        <ProgressBar value={vocabPercent} color="accent" />
        <p className="text-xs text-muted-foreground mt-2">
          {flashcardStats.learned} of {flashcardStats.total} mastered
          {flashcardStats.due > 0 && ` \u00b7 ${flashcardStats.due} due for review`}
        </p>
      </Card>

      <Card>
        <h3 className="text-sm font-medium text-muted-foreground mb-2">
          Lessons
        </h3>
        <p className="text-2xl font-bold text-foreground mb-2">
          {completedLessons}/{totalLessons}
        </p>
        <ProgressBar
          value={totalLessons > 0 ? (completedLessons / totalLessons) * 100 : 0}
        />
        <p className="text-xs text-muted-foreground mt-2">
          {totalLessons > 0
            ? `${totalLessons - completedLessons} remaining`
            : "Coming soon"}
        </p>
      </Card>
    </div>
  );
}

