"use client";

import { useState } from "react";
import type { VocabularyEntry } from "@/types";

interface FlashcardProps {
  card: VocabularyEntry;
  onFlip?: (isFlipped: boolean) => void;
}

export function Flashcard({ card, onFlip }: FlashcardProps) {
  const [flipped, setFlipped] = useState(false);

  const handleFlip = () => {
    const next = !flipped;
    setFlipped(next);
    onFlip?.(next);
  };

  return (
    <div
      className="flashcard-container w-full max-w-md mx-auto cursor-pointer"
      onClick={handleFlip}
    >
      <div className={`flashcard-inner w-full h-64 ${flipped ? "flipped" : ""}`}>
        {/* Front */}
        <div className="flashcard-front flex flex-col items-center justify-center rounded-[var(--radius)] border border-border bg-card p-8">
          <span className="text-3xl font-bold text-foreground mb-2">
            {card.term}
          </span>
          {card.reading && (
            <span className="text-lg text-muted-foreground">{card.reading}</span>
          )}
          <span className="text-xs text-muted-foreground mt-4">Tap to reveal</span>
        </div>

        {/* Back */}
        <div className="flashcard-back flex flex-col items-center justify-center rounded-[var(--radius)] border border-border bg-card p-8">
          <span className="text-2xl font-bold text-foreground mb-2">
            {card.definition}
          </span>
          {card.audioHint && (
            <span className="text-sm text-muted-foreground mb-2">
              [{card.audioHint}]
            </span>
          )}
          {card.exampleSentence && (
            <span className="text-sm text-muted-foreground text-center mt-2 italic">
              {card.exampleSentence}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

