"use client";

import { Button } from "@/components/ui/button";
import type { SM2Rating } from "@/types";

interface FlashcardControlsProps {
  onRate: (rating: SM2Rating) => void;
  disabled?: boolean;
}

const ratings: { rating: SM2Rating; label: string; color: string }[] = [
  { rating: 0, label: "Again", color: "bg-destructive text-white hover:bg-destructive/80" },
  { rating: 3, label: "Hard", color: "bg-orange-500 text-white hover:bg-orange-600" },
  { rating: 4, label: "Good", color: "bg-primary text-primary-foreground hover:bg-primary-hover" },
  { rating: 5, label: "Easy", color: "bg-accent text-accent-foreground hover:bg-accent/80" },
];

export function FlashcardControls({ onRate, disabled }: FlashcardControlsProps) {
  return (
    <div className="flex gap-3 justify-center mt-6">
      {ratings.map(({ rating, label, color }) => (
        <button
          key={rating}
          onClick={() => onRate(rating)}
          disabled={disabled}
          className={`px-5 py-2.5 rounded-[var(--radius)] text-sm font-medium transition-colors cursor-pointer disabled:opacity-50 disabled:pointer-events-none ${color}`}
        >
          {label}
        </button>
      ))}
    </div>
  );
}

