"use client";

import { useEffect, useState } from "react";
import { Flashcard } from "./flashcard";
import { FlashcardControls } from "./flashcard-controls";
import { FlashcardStats } from "./flashcard-stats";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { useFlashcards } from "@/contexts/flashcard-context";
import { useApp } from "@/contexts/app-context";
import { getLanguage } from "@/data/languages";

export function FlashcardPage() {
  const { selectedLanguage } = useApp();
  const {
    session,
    currentCard,
    isSessionComplete,
    startSession,
    rateCard,
  } = useFlashcards();
  const [isFlipped, setIsFlipped] = useState(false);

  // Reset flip state when card changes
  useEffect(() => {
    setIsFlipped(false);
  }, [currentCard?.id]);

  if (!selectedLanguage) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">
          Please select a language from the dashboard first.
        </p>
      </div>
    );
  }

  const language = getLanguage(selectedLanguage);

  // No session started yet
  if (!session) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center space-y-6">
        <h1 className="text-2xl font-bold text-foreground">
          Flashcards {language.flag}
        </h1>
        <p className="text-muted-foreground">
          Review your {language.name} vocabulary using spaced repetition.
          Cards you know well appear less often.
        </p>
        <Button size="lg" onClick={startSession}>
          Start Study Session
        </Button>
      </div>
    );
  }

  // Session complete
  if (isSessionComplete) {
    const accuracy =
      session.reviewed > 0
        ? Math.round((session.correct / session.reviewed) * 100)
        : 0;

    return (
      <div className="p-6 max-w-2xl mx-auto text-center space-y-6">
        <h1 className="text-2xl font-bold text-foreground">Session Complete!</h1>
        <Card className="max-w-sm mx-auto">
          <div className="space-y-3">
            <p className="text-4xl font-bold text-primary">{accuracy}%</p>
            <p className="text-muted-foreground">
              {session.correct} correct out of {session.reviewed} cards
            </p>
          </div>
        </Card>
        <Button size="lg" onClick={startSession}>
          Study Again
        </Button>
      </div>
    );
  }

  // Active session
  return (
    <div className="p-6 max-w-2xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-foreground">
          Flashcards {language.flag}
        </h1>
      </div>

      <FlashcardStats
        total={session.cards.length}
        reviewed={session.reviewed}
        correct={session.correct}
      />

      {currentCard && (
        <>
          <Flashcard card={currentCard} onFlip={setIsFlipped} />
          {isFlipped && (
            <FlashcardControls onRate={rateCard} />
          )}
          {!isFlipped && (
            <p className="text-center text-sm text-muted-foreground">
              Tap the card to reveal the answer
            </p>
          )}
        </>
      )}
    </div>
  );
}

