import type { Lesson } from "@/types";

export const japaneseLessons: Lesson[] = [
  {
    id: "ja-lesson-001",
    languageCode: "ja",
    title: "Greetings & Introductions",
    description: "Learn essential Japanese greetings and how to introduce yourself.",
    order: 1,
    vocabularyIds: [
      "ja-vocab-001",
      "ja-vocab-002",
      "ja-vocab-003",
      "ja-vocab-006",
    ],
    grammar: [
      {
        title: "Self-introduction with \u301Cです (desu)",
        explanation:
          "To introduce yourself, use the pattern: [Name] です (desu). です is a copula similar to \"am/is/are\" in English. It makes the sentence polite.",
        examples: [
          { target: "田中です。", english: "I am Tanaka." },
          { target: "学生です。", english: "I am a student." },
        ],
      },
      {
        title: "Asking someone's name with \u301Cは\u301Cですか",
        explanation:
          "To ask a question, add か (ka) at the end of a statement. は (wa) marks the topic of the sentence.",
        examples: [
          { target: "お名前は何ですか？", english: "What is your name?" },
          { target: "元気ですか？", english: "Are you well?" },
        ],
      },
    ],
    quizId: "ja-quiz-001",
  },
  {
    id: "ja-lesson-002",
    languageCode: "ja",
    title: "Basic Verbs & Actions",
    description: "Learn common everyday verbs and how to use them in sentences.",
    order: 2,
    vocabularyIds: [
      "ja-vocab-008",
      "ja-vocab-009",
      "ja-vocab-010",
      "ja-vocab-011",
    ],
    grammar: [
      {
        title: "Verb forms: Dictionary vs Masu",
        explanation:
          "Japanese verbs have a casual form (dictionary form) and a polite form (masu form). Use masu form in polite conversation. For ru-verbs, drop る and add ます.",
        examples: [
          { target: "食べる → 食べます", english: "to eat → eat (polite)" },
          { target: "見る → 見ます", english: "to see → see (polite)" },
        ],
      },
      {
        title: "Object marker を (wo/o)",
        explanation:
          "The particle を marks the direct object of a verb — the thing being acted upon.",
        examples: [
          { target: "水を飲む。", english: "Drink water." },
          { target: "本を読む。", english: "Read a book." },
        ],
      },
    ],
    quizId: "ja-quiz-002",
  },
  {
    id: "ja-lesson-003",
    languageCode: "ja",
    title: "Everyday Nouns & Adjectives",
    description: "Build your vocabulary with common nouns and descriptive adjectives.",
    order: 3,
    vocabularyIds: [
      "ja-vocab-012",
      "ja-vocab-013",
      "ja-vocab-014",
      "ja-vocab-015",
      "ja-vocab-016",
      "ja-vocab-017",
      "ja-vocab-018",
      "ja-vocab-019",
      "ja-vocab-020",
    ],
    grammar: [
      {
        title: "i-adjectives",
        explanation:
          "Adjectives ending in い (i) are called i-adjectives. They can directly modify nouns or end a sentence. To negate, drop い and add くない.",
        examples: [
          { target: "大きい犬", english: "a big dog" },
          { target: "小さくない", english: "not small" },
        ],
      },
      {
        title: "Expressing likes with が好きです",
        explanation:
          "To say you like something, use: [thing] が好きです (ga suki desu). The particle が marks the thing you like.",
        examples: [
          { target: "猫が好きです。", english: "I like cats." },
          { target: "本が好きです。", english: "I like books." },
        ],
      },
    ],
  },
];

