import type { Language, VocabularyEntry, Lesson, Quiz, LanguageCode } from "@/types";
import { japaneseVocabulary } from "./japanese/vocabulary";

export const languages: Language[] = [
  { code: "ja", name: "Japanese", nativeName: "日本語", flag: "\u{1F1EF}\u{1F1F5}" },
  { code: "es", name: "Spanish", nativeName: "Espa\u00f1ol", flag: "\u{1F1EA}\u{1F1F8}" },
  { code: "fr", name: "French", nativeName: "Fran\u00e7ais", flag: "\u{1F1EB}\u{1F1F7}" },
];

interface LanguageContent {
  vocabulary: VocabularyEntry[];
  lessons: Lesson[];
  quizzes: Quiz[];
}

const contentMap: Partial<Record<LanguageCode, LanguageContent>> = {
  ja: { vocabulary: japaneseVocabulary, lessons: [], quizzes: [] },
};

export function getLanguageContent(code: LanguageCode): LanguageContent {
  return contentMap[code] ?? { vocabulary: [], lessons: [], quizzes: [] };
}

export function getLanguage(code: LanguageCode): Language {
  return languages.find((l) => l.code === code)!;
}

export function getAvailableLanguages(): Language[] {
  return languages.filter((l) => contentMap[l.code] !== undefined);
}

