"use client";

import Link from "next/link";
import { Card } from "@/components/ui/card";
import type { Lesson, LessonProgress } from "@/types";

interface LessonCardProps {
  lesson: Lesson;
  progress?: LessonProgress;
  index: number;
}

export function LessonCard({ lesson, progress, index }: LessonCardProps) {
  const isCompleted = progress?.completed ?? false;

  return (
    <Link href={`/lessons/${lesson.id}`}>
      <Card className="hover:border-primary/50 transition-colors cursor-pointer">
        <div className="flex items-start gap-4">
          <div
            className={`flex items-center justify-center w-10 h-10 rounded-full text-sm font-bold shrink-0 ${
              isCompleted
                ? "bg-accent text-accent-foreground"
                : "bg-secondary text-secondary-foreground"
            }`}
          >
            {isCompleted ? "\u2713" : index + 1}
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-foreground">{lesson.title}</h3>
            <p className="text-sm text-muted-foreground mt-1">
              {lesson.description}
            </p>
            <div className="flex gap-3 mt-2 text-xs text-muted-foreground">
              <span>{lesson.vocabularyIds.length} words</span>
              <span>{lesson.grammar.length} grammar points</span>
              {isCompleted && (
                <span className="text-accent font-medium">Completed</span>
              )}
            </div>
          </div>
        </div>
      </Card>
    </Link>
  );
}

