"use client";

import { useApp } from "@/contexts/app-context";
import { getLanguageContent, getLanguage } from "@/data/languages";
import { LessonCard } from "./lesson-card";

export function LessonsListPage() {
  const { selectedLanguage, lessonProgress } = useApp();

  if (!selectedLanguage) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">
          Please select a language from the dashboard first.
        </p>
      </div>
    );
  }

  const language = getLanguage(selectedLanguage);
  const content = getLanguageContent(selectedLanguage);
  const sortedLessons = [...content.lessons].sort((a, b) => a.order - b.order);

  const progressMap = Object.fromEntries(
    lessonProgress.map((p) => [p.lessonId, p])
  );

  return (
    <div className="p-6 max-w-3xl mx-auto space-y-4">
      <h1 className="text-2xl font-bold text-foreground">
        {language.name} Lessons {language.flag}
      </h1>
      <p className="text-muted-foreground">
        {sortedLessons.length} lessons available.{" "}
        {lessonProgress.filter((p) => p.completed).length} completed.
      </p>
      <div className="space-y-3">
        {sortedLessons.map((lesson, i) => (
          <LessonCard
            key={lesson.id}
            lesson={lesson}
            progress={progressMap[lesson.id]}
            index={i}
          />
        ))}
      </div>
    </div>
  );
}

