"use client";

import { useApp } from "@/contexts/app-context";
import { getLanguageContent } from "@/data/languages";
import { VocabularyTable } from "./vocabulary-table";
import { GrammarBlock } from "./grammar-block";
import { Button } from "@/components/ui/button";
import Link from "next/link";
import type { VocabularyEntry } from "@/types";

interface LessonDetailPageProps {
  lessonId: string;
}

export function LessonDetailPage({ lessonId }: LessonDetailPageProps) {
  const { selectedLanguage, lessonProgress, completeLesson } = useApp();

  if (!selectedLanguage) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">
          Please select a language from the dashboard first.
        </p>
      </div>
    );
  }

  const content = getLanguageContent(selectedLanguage);
  const lesson = content.lessons.find((l) => l.id === lessonId);

  if (!lesson) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">Lesson not found.</p>
        <Link href="/lessons">
          <Button variant="secondary" className="mt-4">
            Back to Lessons
          </Button>
        </Link>
      </div>
    );
  }

  const vocabMap = Object.fromEntries(
    content.vocabulary.map((v) => [v.id, v])
  );
  const lessonVocab: VocabularyEntry[] = lesson.vocabularyIds
    .map((id) => vocabMap[id])
    .filter(Boolean);

  const isCompleted = lessonProgress.some(
    (p) => p.lessonId === lessonId && p.completed
  );

  const handleComplete = () => {
    completeLesson(lessonId);
  };

  return (
    <div className="p-6 max-w-3xl mx-auto space-y-6">
      <div>
        <Link
          href="/lessons"
          className="text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          &larr; Back to Lessons
        </Link>
      </div>

      <div>
        <h1 className="text-2xl font-bold text-foreground">{lesson.title}</h1>
        <p className="text-muted-foreground mt-1">{lesson.description}</p>
      </div>

      {lessonVocab.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold text-foreground mb-3">
            Vocabulary
          </h2>
          <VocabularyTable entries={lessonVocab} />
        </div>
      )}

      {lesson.grammar.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold text-foreground mb-3">Grammar</h2>
          <div className="space-y-4">
            {lesson.grammar.map((concept, i) => (
              <GrammarBlock key={i} concept={concept} />
            ))}
          </div>
        </div>
      )}

      <div className="flex items-center gap-4 pt-4 border-t border-border">
        {isCompleted ? (
          <p className="text-accent font-medium">Lesson completed!</p>
        ) : (
          <Button onClick={handleComplete}>Mark as Complete</Button>
        )}
        {lesson.quizId && (
          <Link href={`/quizzes/${lesson.quizId}`}>
            <Button variant="secondary">Take Quiz</Button>
          </Link>
        )}
      </div>
    </div>
  );
}

