import { japaneseLessons } from "./japanese/lessons";
import { spanishVocabulary } from "./spanish/vocabulary";
import { spanishLessons } from "./spanish/lessons";
import { frenchVocabulary } from "./french/vocabulary";
import { frenchLessons } from "./french/lessons";

export const languages: Language[] = [
  { code: "ja", name: "Japanese", nativeName: "\u65e5\u672c\u8a9e", flag: "\u{1F1EF}\u{1F1F5}" },
  { code: "es", name: "Spanish", nativeName: "Espa\u00f1ol", flag: "\u{1F1EA}\u{1F1F8}" },
  { code: "fr", name: "French", nativeName: "Fran\u00e7ais", flag: "\u{1F1EB}\u{1F1F7}" },
];

interface LanguageContent {
  vocabulary: VocabularyEntry[];
  lessons: Lesson[];
  quizzes: Quiz[];
}

const contentMap: Record<LanguageCode, LanguageContent> = {
  ja: { vocabulary: japaneseVocabulary, lessons: japaneseLessons, quizzes: [] },
  es: { vocabulary: spanishVocabulary, lessons: spanishLessons, quizzes: [] },
  fr: { vocabulary: frenchVocabulary, lessons: frenchLessons, quizzes: [] },
};

export function getLanguageContent(code: LanguageCode): LanguageContent {
  return contentMap[code];
}

export function getLanguage(code: LanguageCode): Language {
  return languages.find((l) => l.code === code)!;
}

export function getAvailableLanguages(): Language[] {
  return languages;
}

