"use client";

import type { QuizQuestion } from "@/types";

interface MultipleChoiceProps {
  question: QuizQuestion;
  selectedAnswer: string | null;
  onAnswer: (answer: string) => void;
  showResult: boolean;
}

export function MultipleChoice({
  question,
  selectedAnswer,
  onAnswer,
  showResult,
}: MultipleChoiceProps) {
  return (
    <div className="space-y-3">
      <p className="text-lg font-medium text-foreground">{question.prompt}</p>
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
        {question.options?.map((option) => {
          const isSelected = selectedAnswer === option;
          const isCorrect = option === question.correctAnswer;

          let className =
            "px-4 py-3 rounded-[var(--radius)] border text-left text-sm font-medium transition-colors cursor-pointer";

          if (showResult) {
            if (isCorrect) {
              className += " border-accent bg-accent/10 text-accent";
            } else if (isSelected && !isCorrect) {
              className += " border-destructive bg-destructive/10 text-destructive";
            } else {
              className += " border-border text-muted-foreground";
            }
          } else if (isSelected) {
            className += " border-primary bg-primary/10 text-primary";
          } else {
            className += " border-border hover:border-primary/50 text-foreground";
          }

          return (
            <button
              key={option}
              onClick={() => !showResult && onAnswer(option)}
              disabled={showResult}
              className={className}
            >
              {option}
            </button>
          );
        })}
      </div>
    </div>
  );
}

