"use client";

import { useState } from "react";
import type { QuizQuestion } from "@/types";

interface FillInBlankProps {
  question: QuizQuestion;
  selectedAnswer: string | null;
  onAnswer: (answer: string) => void;
  showResult: boolean;
}

export function FillInBlank({
  question,
  selectedAnswer,
  onAnswer,
  showResult,
}: FillInBlankProps) {
  const [input, setInput] = useState("");

  const handleSubmit = () => {
    if (input.trim()) {
      onAnswer(input.trim());
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter" && !showResult) {
      handleSubmit();
    }
  };

  const isCorrect =
    selectedAnswer?.toLowerCase() === question.correctAnswer.toLowerCase();

  return (
    <div className="space-y-3">
      <p className="text-lg font-medium text-foreground">{question.prompt}</p>
      {question.sentenceTemplate && (
        <p className="text-base text-muted-foreground font-mono bg-secondary px-4 py-2 rounded-[var(--radius)]">
          {question.sentenceTemplate}
        </p>
      )}
      <div className="flex gap-2">
        <input
          type="text"
          value={showResult ? selectedAnswer ?? "" : input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          disabled={showResult}
          placeholder="Type your answer..."
          className={`flex-1 px-4 py-2.5 rounded-[var(--radius)] border text-sm bg-card text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/50 disabled:opacity-70 ${
            showResult
              ? isCorrect
                ? "border-accent"
                : "border-destructive"
              : "border-border"
          }`}
        />
        {!showResult && (
          <button
            onClick={handleSubmit}
            disabled={!input.trim()}
            className="px-4 py-2.5 rounded-[var(--radius)] bg-primary text-primary-foreground text-sm font-medium cursor-pointer disabled:opacity-50"
          >
            Submit
          </button>
        )}
      </div>
      {showResult && !isCorrect && (
        <p className="text-sm text-muted-foreground">
          Correct answer: <span className="font-medium text-accent">{question.correctAnswer}</span>
        </p>
      )}
    </div>
  );
}

