        <FillInBlank
          question={question}
          selectedAnswer={selectedAnswer}
          onAnswer={onAnswer}
          showResult={showResult}
        />
      );
    case "translation":
      return (
        <Translation
          question={question}
          selectedAnswer={selectedAnswer}
          onAnswer={onAnswer}
          showResult={showResult}
        />
      );
  }
}

