  quizId: string;
}

export function QuizPage({ quizId }: QuizPageProps) {
  const { selectedLanguage, saveQuizAttempt } = useApp();
  const [currentIndex, setCurrentIndex] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [showResult, setShowResult] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [correctCount, setCorrectCount] = useState(0);

  if (!selectedLanguage) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">
          Please select a language from the dashboard first.
        </p>
      </div>
    );
  }

  const language = getLanguage(selectedLanguage);
  const content = getLanguageContent(selectedLanguage);
  const quiz = content.quizzes.find((q) => q.id === quizId);

  if (!quiz) {
    return (
      <div className="p-6 max-w-2xl mx-auto text-center">
        <p className="text-muted-foreground">Quiz not found.</p>
        <Link href="/lessons">
          <Button variant="secondary" className="mt-4">
            Back to Lessons
          </Button>
        </Link>
      </div>
    );
  }

  const currentQuestion = quiz.questions[currentIndex];
  const totalQuestions = quiz.questions.length;
  const progress = ((currentIndex + (showResult ? 1 : 0)) / totalQuestions) * 100;

  const handleAnswer = (answer: string) => {
    setAnswers((prev) => ({ ...prev, [currentQuestion.id]: answer }));
    setShowResult(true);
  };

  const handleNext = () => {
    const isCorrect =
      answers[currentQuestion.id]?.toLowerCase() ===
      currentQuestion.correctAnswer.toLowerCase();

    const newCorrectCount = correctCount + (isCorrect ? 1 : 0);

    if (currentIndex + 1 >= totalQuestions) {
      setCorrectCount(newCorrectCount);
      setIsComplete(true);

      const attempt: QuizAttempt = {
        quizId: quiz.id,
        languageCode: selectedLanguage,
        score: Math.round((newCorrectCount / totalQuestions) * 100),
        totalQuestions,
        correctAnswers: newCorrectCount,
        attemptedAt: new Date().toISOString(),
      };
      saveQuizAttempt(attempt);
    } else {
      setCorrectCount(newCorrectCount);
      setCurrentIndex((prev) => prev + 1);
      setShowResult(false);
    }
  };

  const handleRetry = () => {
    setCurrentIndex(0);
    setAnswers({});
    setShowResult(false);
    setIsComplete(false);
    setCorrectCount(0);
  };

  if (isComplete) {
    return (
      <div className="p-6 max-w-2xl mx-auto">
        <QuizResults
          title={quiz.title}
          totalQuestions={totalQuestions}
          correctAnswers={correctCount}
          onRetry={handleRetry}
        />
      </div>
    );
  }

  return (
    <div className="p-6 max-w-2xl mx-auto space-y-6">
      <div>
        <Link
          href="/lessons"
          className="text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          &larr; Back to Lessons
        </Link>
      </div>

      <div>
        <h1 className="text-2xl font-bold text-foreground">
          {quiz.title} {language.flag}
        </h1>
        <div className="flex items-center gap-3 mt-2">
          <ProgressBar value={progress} className="flex-1" />
          <span className="text-sm text-muted-foreground shrink-0">
            {currentIndex + 1}/{totalQuestions}
          </span>
        </div>
      </div>

      <Card>
        <QuizQuestion
          key={currentQuestion.id}
          question={currentQuestion}
          selectedAnswer={answers[currentQuestion.id] ?? null}
          onAnswer={handleAnswer}
          showResult={showResult}
        />
      </Card>

      {showResult && (
        <div className="flex justify-end">
          <Button onClick={handleNext}>
            {currentIndex + 1 >= totalQuestions ? "See Results" : "Next Question"}
          </Button>
        </div>
      )}
    </div>
  );
}

