"use client";

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  type ReactNode,
} from "react";
import type {
  UserProfile,
  LanguageCode,
  LessonProgress,
  QuizAttempt,
} from "@/types";
import { getStorage } from "@/lib/storage";
import { generateId } from "@/lib/utils";

interface AppContextValue {
  profile: UserProfile | null;
  isLoading: boolean;
  selectedLanguage: LanguageCode | null;
  selectLanguage: (code: LanguageCode) => Promise<void>;
  completeLesson: (lessonId: string) => Promise<void>;
  saveQuizAttempt: (attempt: QuizAttempt) => Promise<void>;
  lessonProgress: LessonProgress[];
  quizAttempts: QuizAttempt[];
}

const AppContext = createContext<AppContextValue | null>(null);

export function AppProvider({ children }: { children: ReactNode }) {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [lessonProgress, setLessonProgress] = useState<LessonProgress[]>([]);
  const [quizAttempts, setQuizAttempts] = useState<QuizAttempt[]>([]);

  const selectedLanguage = profile?.selectedLanguage ?? null;

  useEffect(() => {
    const storage = getStorage();
    storage.getProfile().then((p) => {
      setProfile(p);
      setIsLoading(false);
    });
  }, []);

  useEffect(() => {
    if (!selectedLanguage) return;
    const storage = getStorage();
    storage.getAllLessonProgress(selectedLanguage).then(setLessonProgress);
  }, [selectedLanguage]);

  const selectLanguage = useCallback(async (code: LanguageCode) => {
    const storage = getStorage();
    const existing = await storage.getProfile();
    const updated: UserProfile = existing
      ? { ...existing, selectedLanguage: code }
      : { id: generateId(), selectedLanguage: code, createdAt: new Date().toISOString() };
    await storage.saveProfile(updated);
    setProfile(updated);
  }, []);

  const completeLesson = useCallback(
    async (lessonId: string) => {
      if (!selectedLanguage) return;
      const storage = getStorage();
      const progress: LessonProgress = {
        lessonId,
        languageCode: selectedLanguage,
        completed: true,
        completedAt: new Date().toISOString(),
      };
      await storage.saveLessonProgress(progress);
      setLessonProgress((prev) => {
        const filtered = prev.filter((p) => p.lessonId !== lessonId);
        return [...filtered, progress];
      });
    },
    [selectedLanguage]
  );

  const saveQuizAttempt = useCallback(async (attempt: QuizAttempt) => {
    const storage = getStorage();
    await storage.saveQuizAttempt(attempt);
    setQuizAttempts((prev) => [...prev, attempt]);
  }, []);

  return (
    <AppContext.Provider
      value={{
        profile,
        isLoading,
        selectedLanguage,
        selectLanguage,
        completeLesson,
        saveQuizAttempt,
        lessonProgress,
        quizAttempts,
      }}
    >
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error("useApp must be used within AppProvider");
  return ctx;
}

