"use client";

import { type FormEvent } from "react";

interface ConversationInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (e: FormEvent) => void;
  isLoading: boolean;
}

export function ConversationInput({
  value,
  onChange,
  onSubmit,
  isLoading,
}: ConversationInputProps) {
  return (
    <form onSubmit={onSubmit} className="flex gap-2">
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder="Type a message..."
        disabled={isLoading}
        className="flex-1 px-4 py-2.5 rounded-[var(--radius)] border border-border bg-card text-foreground placeholder:text-muted-foreground text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 disabled:opacity-50"
      />
      <button
        type="submit"
        disabled={isLoading || !value.trim()}
        className="px-4 py-2.5 rounded-[var(--radius)] bg-primary text-primary-foreground text-sm font-medium cursor-pointer disabled:opacity-50 disabled:pointer-events-none"
      >
        {isLoading ? "..." : "Send"}
      </button>
    </form>
  );
}

