import { streamText } from "ai";
import { anthropic } from "@ai-sdk/anthropic";

export async function POST(request: Request) {
  const { messages, languageName } = await request.json();

  const systemPrompt = `You are a friendly and patient ${languageName} language tutor. Your role:

1. Conduct conversations primarily in ${languageName}
2. Provide English translations in parentheses for words the learner might not know
3. Gently correct any mistakes the learner makes
4. Adjust complexity based on the learner's level
5. Keep responses concise (2-3 sentences)
6. Occasionally introduce new vocabulary relevant to the conversation

Start by greeting the learner in ${languageName} and asking what they'd like to practice.`;

  const result = streamText({
    model: anthropic("claude-haiku-4-5"),
    system: systemPrompt,
    messages,
    maxTokens: 300,
  });

  return result.toDataStreamResponse();
}

