import type { Language, VocabularyEntry, Lesson, Quiz, LanguageCode } from "@/types";
import { japaneseVocabulary } from "./japanese/vocabulary";
import { japaneseLessons } from "./japanese/lessons";
import { spanishVocabulary } from "./spanish/vocabulary";
import { spanishLessons } from "./spanish/lessons";
import { frenchVocabulary } from "./french/vocabulary";
import { frenchLessons } from "./french/lessons";
import { japaneseQuizzes } from "./japanese/quizzes";
import { spanishQuizzes } from "./spanish/quizzes";
import { frenchQuizzes } from "./french/quizzes";

export const languages: Language[] = [
  { code: "ja", name: "Japanese", nativeName: "\u65e5\u672c\u8a9e", flag: "\u{1F1EF}\u{1F1F5}" },
  { code: "es", name: "Spanish", nativeName: "Espa\u00f1ol", flag: "\u{1F1EA}\u{1F1F8}" },
  { code: "fr", name: "French", nativeName: "Fran\u00e7ais", flag: "\u{1F1EB}\u{1F1F7}" },
];

interface LanguageContent {
  vocabulary: VocabularyEntry[];
  lessons: Lesson[];
  quizzes: Quiz[];
}

const contentMap: Record<LanguageCode, LanguageContent> = {
  ja: { vocabulary: japaneseVocabulary, lessons: japaneseLessons, quizzes: japaneseQuizzes },
  es: { vocabulary: spanishVocabulary, lessons: spanishLessons, quizzes: spanishQuizzes },
  fr: { vocabulary: frenchVocabulary, lessons: frenchLessons, quizzes: frenchQuizzes },
};

export function getLanguageContent(code: LanguageCode): LanguageContent {
  return contentMap[code];
}

export function getLanguage(code: LanguageCode): Language {
  return languages.find((l) => l.code === code)!;
}

export function getAvailableLanguages(): Language[] {
  return languages;
}

import type { Lesson } from "@/types";

export const japaneseLessons: Lesson[] = [
  {
    id: "ja-lesson-001",
    languageCode: "ja",
    title: "Greetings & Introductions",
    description: "Learn essential Japanese greetings and how to introduce yourself.",
    order: 1,
    vocabularyIds: [
      "ja-vocab-001",
      "ja-vocab-002",
      "ja-vocab-003",
      "ja-vocab-006",
    ],
    grammar: [
      {
        title: "Self-introduction with \u301Cです (desu)",
        explanation:
          "To introduce yourself, use the pattern: [Name] です (desu). です is a copula similar to \"am/is/are\" in English. It makes the sentence polite.",
        examples: [
          { target: "田中です。", english: "I am Tanaka." },
          { target: "学生です。", english: "I am a student." },
        ],
      },
      {
        title: "Asking someone's name with \u301Cは\u301Cですか",
        explanation:
          "To ask a question, add か (ka) at the end of a statement. は (wa) marks the topic of the sentence.",
        examples: [
          { target: "お名前は何ですか？", english: "What is your name?" },
          { target: "元気ですか？", english: "Are you well?" },
        ],
      },
    ],
    quizId: "ja-quiz-001",
  },
  {
    id: "ja-lesson-002",
    languageCode: "ja",
    title: "Basic Verbs & Actions",
    description: "Learn common everyday verbs and how to use them in sentences.",
    order: 2,
    vocabularyIds: [
      "ja-vocab-008",
      "ja-vocab-009",
      "ja-vocab-010",
      "ja-vocab-011",
    ],
    grammar: [
      {
        title: "Verb forms: Dictionary vs Masu",
        explanation:
          "Japanese verbs have a casual form (dictionary form) and a polite form (masu form). Use masu form in polite conversation. For ru-verbs, drop る and add ます.",
        examples: [
          { target: "食べる → 食べます", english: "to eat → eat (polite)" },
          { target: "見る → 見ます", english: "to see → see (polite)" },
        ],
      },
      {
        title: "Object marker を (wo/o)",
        explanation:
          "The particle を marks the direct object of a verb — the thing being acted upon.",
        examples: [
          { target: "水を飲む。", english: "Drink water." },
          { target: "本を読む。", english: "Read a book." },
        ],
      },
    ],
    quizId: "ja-quiz-002",
  },
  {
    id: "ja-lesson-003",
    languageCode: "ja",
    title: "Everyday Nouns & Adjectives",
    description: "Build your vocabulary with common nouns and descriptive adjectives.",
    order: 3,
    vocabularyIds: [
      "ja-vocab-012",
      "ja-vocab-013",
      "ja-vocab-014",
      "ja-vocab-015",
      "ja-vocab-016",
      "ja-vocab-017",
      "ja-vocab-018",
      "ja-vocab-019",
      "ja-vocab-020",
    ],
    grammar: [
      {
        title: "i-adjectives",
        explanation:
          "Adjectives ending in い (i) are called i-adjectives. They can directly modify nouns or end a sentence. To negate, drop い and add くない.",
        examples: [
          { target: "大きい犬", english: "a big dog" },
          { target: "小さくない", english: "not small" },
        ],
      },
      {
        title: "Expressing likes with が好きです",
        explanation:
          "To say you like something, use: [thing] が好きです (ga suki desu). The particle が marks the thing you like.",
        examples: [
          { target: "猫が好きです。", english: "I like cats." },
          { target: "本が好きです。", english: "I like books." },
        ],
      },
    ],
  },
];

import type { Quiz } from "@/types";

export const japaneseQuizzes: Quiz[] = [
  {
    id: "ja-quiz-001",
    languageCode: "ja",
    lessonId: "ja-lesson-001",
    title: "Greetings & Introductions Quiz",
    questions: [
      {
        id: "ja-q-001",
        type: "multiple-choice",
        prompt: "What does \u201c\u3053\u3093\u306b\u3061\u306f\u201d mean?",
        options: ["Goodbye", "Thank you", "Hello", "Excuse me"],
        correctAnswer: "Hello",
      },
      {
        id: "ja-q-002",
        type: "multiple-choice",
        prompt: "How do you say \u201cThank you\u201d in Japanese?",
        options: ["\u3053\u3093\u306b\u3061\u306f", "\u3042\u308a\u304c\u3068\u3046", "\u3055\u3088\u3046\u306a\u3089", "\u3059\u307f\u307e\u305b\u3093"],
        correctAnswer: "\u3042\u308a\u304c\u3068\u3046",
      },
      {
        id: "ja-q-003",
        type: "translation",
        prompt: "Translate to English: \u3055\u3088\u3046\u306a\u3089",
        correctAnswer: "Goodbye",
      },
      {
        id: "ja-q-004",
        type: "fill-in-blank",
        prompt: "Complete the sentence to say \u201cI am Tanaka\u201d",
        sentenceTemplate: "\u7530\u4e2d___\u3002",
        correctAnswer: "\u3067\u3059",
      },
      {
        id: "ja-q-005",
        type: "multiple-choice",
        prompt: "What does \u201c\u3059\u307f\u307e\u305b\u3093\u201d mean?",
        options: ["Hello", "Please", "Excuse me / I'm sorry", "Yes"],
        correctAnswer: "Excuse me / I'm sorry",
      },
    ],
  },
  {
    id: "ja-quiz-002",
    languageCode: "ja",
    lessonId: "ja-lesson-002",
    title: "Basic Verbs & Actions Quiz",
    questions: [
      {
        id: "ja-q-006",
        type: "multiple-choice",
        prompt: "What does \u201c\u98df\u3079\u308b\u201d (taberu) mean?",
        options: ["To drink", "To go", "To eat", "To see"],
        correctAnswer: "To eat",
      },
      {
        id: "ja-q-007",
        type: "translation",
        prompt: "Translate to English: \u6c34\u3092\u98f2\u3080",
        correctAnswer: "Drink water",
      },
      {
        id: "ja-q-008",
        type: "multiple-choice",
        prompt: "What is the polite (masu) form of \u898b\u308b (miru)?",
        options: ["\u898b\u307e\u3059", "\u898b\u308b\u307e\u3059", "\u898b\u305f", "\u898b\u306a\u3044"],
        correctAnswer: "\u898b\u307e\u3059",
      },
      {
        id: "ja-q-009",
        type: "fill-in-blank",
        prompt: "Fill in the particle: \u672c___\u8aad\u3080 (read a book)",
        sentenceTemplate: "\u672c___\u8aad\u3080",
        correctAnswer: "\u3092",
      },
      {
        id: "ja-q-010",
        type: "translation",
        prompt: "Translate to English: \u5b66\u6821\u306b\u884c\u304f",
        correctAnswer: "Go to school",
      },
    ],
  },
];

